candidates.raw:
    adcs_vec3_t na, nb;
    double sep, selected_var;
    adcs_status_t st;

    if ((body_a == NULL) || (body_b == NULL) || (ref_a == NULL) || (ref_b == NULL) ||
        (primary_index == NULL) || (geometry_quality == NULL) || (c_bi == NULL))
        return ADCS_E_NULL;

    if ((!isfinite(variance_a)) || (!isfinite(variance_b)) || (variance_a <= 0.0) ||
        (variance_b <= 0.0))
        return ADCS_E_RANGE;

    if (adcs_vec3_normalize(ref_a, ADCS_EPS_NORM, &na) != ADCS_OK)
        return ADCS_E_RANGE;
    if (adcs_vec3_normalize(ref_b, ADCS_EPS_NORM, &nb) != ADCS_OK)
        return ADCS_E_RANGE;

    {
        adcs_vec3_t cr = adcs_vec3_cross(&na, &nb);
        sep = adcs_vec3_norm(&cr);
    }
    if (sep <= ADCS_EPS_COLLINEAR)
        return ADCS_E_DEGENERATE;

    if (variance_a <= variance_b) {
        *primary_index = 0;
        selected_var = variance_a;
        st = adcs_triad(body_a, body_b, ref_a, ref_b, c_bi);
    } else {
        *primary_index = 1;
        selected_var = variance_b;
        st = adcs_triad(body_b, body_a, ref_b, ref_a, c_bi);
    }
    if (st != ADCS_OK)
        return st;

    *geometry_quality = sep / selected_var;
    return ADCS_OK;
}

